  "beerZero": [
    "<p><strong>Crisp beer:</strong> Ol' Beautiful Okami Kasu Japanese Lager, Banded Peak Mount Crushmore Pilsner, Stella Artois, Michelob Ultra. Use for fries, oysters, garlic bread, and Margherita.</p>",
    "<p><strong>Hoppy beer:</strong> Establishment Afternoon Delight NEPA, 33 Acres Ocean Pale Ale, Superflux Happyness IPA, Banded Peak Microburst Hazy IPA. Use for salami, sausage, hummus chips, eggplant fries.</p>",
    "<p><strong>Sour/fruity:</strong> Four Winds Nectarous, Dandy The Julia Peach Cobbler Sour, Polyrhythm Matinee Lemon Cream Tart Ale, Uncommon Tropical Cider. Use for burrata, octopus, Apple Tatin, Banana Pie.</p>",
    "<p><strong>Rich beer:</strong> Born Arm Candy Milk Stout or Chimay Blue. Use for steak, ribeye, or Chocolate Pot de Crème.</p>",
    "<p><strong>No-alcohol wine:</strong> Gallina de Piel Neverwine for seafood, Freixenet Sparkling Wine for bubbles, Noughty Rouge for soft red-fruit pairings.</p>"
  ],
